import { fixturePath, walkDirectory } from '@phanes/testkit';
import { describe, expect, it } from 'vitest';
import { loadProject } from '../src';

const SDKS = ['6.99.14.3', '7.4.11', '8.3.7', '8.5.3'] as const;

/** Identifiers that the 8.5.3 tl/french files (generated by Ren'Py) translate. */
const TRANSLATED = [
  'park_3feb0781',
  'start_842c8915',
  'start_c2dc35f4',
  'start_d6ab0810',
  'start_f9d2b1c6',
];

for (const sdk of SDKS) {
  for (const layout of ['project', 'dist'] as const) {
    describe(`translation identifiers of the Ren'Py ${sdk} ${layout}`, async () => {
      const project = await loadProject(
        await walkDirectory(fixturePath('build', sdk, 'phanes_demo', layout)),
      );
      const ids = project.translationIds?.ids ?? [];

      it('are read from slot 2 of every default-language script', () => {
        expect(project.translationIds?.unavailable).toEqual([]);
        expect(ids).toHaveLength(18);
        expect(new Set(ids.map((i) => i.id)).size).toBe(18);
        expect(ids.filter((i) => !i.hasSay).map((i) => i.label)).toEqual(['good_ending']);
        expect(ids.filter((i) => i.loc.file === 'game/story/extra.rpy')).toHaveLength(2);
      });

      it('match the identifiers used by the translation', () => {
        const known = new Set(ids.map((i) => i.id));
        for (const id of TRANSLATED) expect(known.has(id), id).toBe(true);
        const start = ids.find((i) => i.id === 'start_f9d2b1c6');
        expect(start).toMatchObject({ label: 'start', loc: { file: 'game/script.rpy', line: 13 } });
      });
    });
  }
}
